// F = fixed per-call cost (RTT / syscall / commit), V = marginal per-item cost.
const F = 250;   // e.g. 250 ms round-trip, the dominating fixed cost
const V = 0.01;  // tiny marginal cost per item

function unbatched(N) { return N * (F + V); }        // pay F every item
function batched(N)   { return F + N * V; }          // pay F once

for (const N of [1, 10, 100, 1000, 10000]) {
  const perItem = batched(N) / N;                    // amortized cost per item
  console.log(`N=${N}  unbatched=${unbatched(N).toFixed(2)}  batched=${batched(N).toFixed(2)}  perItem=${perItem.toFixed(4)}`);
}
console.log(`marginal V=${V}`);
